BEGIN;
CREATE TEMP TABLE curriculum_revised (payload jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO curriculum_revised(payload) VALUES ($guide_payload$[{"slug":"talora-social-media-management-2026","task_number":1,"title":"Brand Channel Audit","old_instructions":"[[AZ]]\n## Məqsəd\nNümunə brendin açıq hesablarını seç ;  Üç güclü və üç zəif tərəf yaz ;  Nəticələri screenshot yox, ölçü ilə sübut et.\n\n## Addım-addım icra\n1. Nümunə brendin açıq hesablarını seç.\n2. Üç güclü və üç zəif tərəf yaz.\n3. Nəticələri screenshot yox, ölçü ilə sübut et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nChannel audit report. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nChoose public brand profiles ;  Find three strengths and weaknesses ;  Ground findings in measurable observations.\n\n## Step-by-step\n1. Choose public brand profiles.\n2. Find three strengths and weaknesses.\n3. Ground findings in measurable observations.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nChannel audit report. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nNümunə brendin açıq hesablarını seç ;  Üç güclü və üç zəif tərəf yaz ;  Nəticələri screenshot yox, ölçü ilə sübut et.\n\n[[EN]]\nChoose public brand profiles ;  Find three strengths and weaknesses ;  Ground findings in measurable observations.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Brand Channel Audit\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Tapşırıq real hesablara giriş tələb etmir: etik kontent planı hazırlayırsan.\n**Nümunə situasiya:** İki universitet klubunun açıq Instagram hesabında paylaşım ardıcıllığını müqayisə et.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Social Media Management / Task-1. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Nümunə brendin açıq hesablarını seç. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Üç güclü və üç zəif tərəf yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Nəticələri screenshot yox, ölçü ilə sübut et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: İki universitet klubunun açıq Instagram hesabında paylaşım ardıcıllığını müqayisə et. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Channel audit report. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nİki universitet klubunun açıq Instagram hesabında paylaşım ardıcıllığını müqayisə et.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Channel audit report.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Şifrə və şəxsi mesaj tələb etmə, faktı yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Brand Channel Audit\nThis practical assignment is designed for beginners. Work on an ethical content plan without accessing real accounts.\n**Example scenario:** Compare posting cadence on two public university club profiles.\n\n## Free tools and platforms\n- **Google Sheets** — https://sheets.google.com. Create a sheet, name the columns and add at least five fictional rows.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Social Media Management / Task-1. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Choose public brand profiles. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Find three strengths and weaknesses. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Ground findings in measurable observations. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Compare posting cadence on two public university club profiles. Document what worked and any limitations.\n7. Complete the main artifact: Channel audit report. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nCompare posting cadence on two public university club profiles.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Channel audit report.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Do not request passwords or private messages; verify facts.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nBrand Channel Audit: Nümunə brendin açıq hesablarını seç. Üç güclü və üç zəif tərəf yaz. Nəticələri screenshot yox, ölçü ilə sübut et. Pulsuz alətlər: Google Sheets. Nəticə: Channel audit report.\n\n[[EN]]\nBrand Channel Audit: Choose public brand profiles. Find three strengths and weaknesses. Ground findings in measurable observations. Free tools: Google Sheets. Output: Channel audit report."},{"slug":"talora-social-media-management-2026","task_number":2,"title":"Audience and Goals","old_instructions":"[[AZ]]\n## Məqsəd\nİki persona qur ;  Sosial media məqsədlərini business goal ilə bağla ;  Üç KPI seç.\n\n## Addım-addım icra\n1. İki persona qur.\n2. Sosial media məqsədlərini business goal ilə bağla.\n3. Üç KPI seç.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nAudience/KPI brief. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nBuild two personas ;  Map channel goals to business outcomes ;  Choose three KPIs.\n\n## Step-by-step\n1. Build two personas.\n2. Map channel goals to business outcomes.\n3. Choose three KPIs.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nAudience/KPI brief. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nİki persona qur ;  Sosial media məqsədlərini business goal ilə bağla ;  Üç KPI seç.\n\n[[EN]]\nBuild two personas ;  Map channel goals to business outcomes ;  Choose three KPIs.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Audience and Goals\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Tapşırıq real hesablara giriş tələb etmir: etik kontent planı hazırlayırsan.\n**Nümunə situasiya:** Birinci kurs tələbəsi və məzun üçün iki persona və ayrı KPI yaz.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Social Media Management / Task-2. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. İki persona qur. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Sosial media məqsədlərini business goal ilə bağla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Üç KPI seç. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Birinci kurs tələbəsi və məzun üçün iki persona və ayrı KPI yaz. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Audience/KPI brief. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nBirinci kurs tələbəsi və məzun üçün iki persona və ayrı KPI yaz.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Audience/KPI brief.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Şifrə və şəxsi mesaj tələb etmə, faktı yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Audience and Goals\nThis practical assignment is designed for beginners. Work on an ethical content plan without accessing real accounts.\n**Example scenario:** Create separate personas and KPIs for a first-year student and recent graduate.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Social Media Management / Task-2. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Build two personas. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Map channel goals to business outcomes. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Choose three KPIs. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Create separate personas and KPIs for a first-year student and recent graduate. Document what worked and any limitations.\n7. Complete the main artifact: Audience/KPI brief. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nCreate separate personas and KPIs for a first-year student and recent graduate.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Audience/KPI brief.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Do not request passwords or private messages; verify facts.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nAudience and Goals: İki persona qur. Sosial media məqsədlərini business goal ilə bağla. Üç KPI seç. Pulsuz alətlər: Google Docs. Nəticə: Audience/KPI brief.\n\n[[EN]]\nAudience and Goals: Build two personas. Map channel goals to business outcomes. Choose three KPIs. Free tools: Google Docs. Output: Audience/KPI brief."},{"slug":"talora-social-media-management-2026","task_number":3,"title":"Content Pillars","old_instructions":"[[AZ]]\n## Məqsəd\nDörd kontent sütunu müəyyən et ;  Hər biri üçün üç ideya yaz ;  Kontent dəyərini izah et.\n\n## Addım-addım icra\n1. Dörd kontent sütunu müəyyən et.\n2. Hər biri üçün üç ideya yaz.\n3. Kontent dəyərini izah et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nContent pillars matrix. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nDefine four content pillars ;  Draft three ideas per pillar ;  Explain value to the audience.\n\n## Step-by-step\n1. Define four content pillars.\n2. Draft three ideas per pillar.\n3. Explain value to the audience.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nContent pillars matrix. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nDörd kontent sütunu müəyyən et ;  Hər biri üçün üç ideya yaz ;  Kontent dəyərini izah et.\n\n[[EN]]\nDefine four content pillars ;  Draft three ideas per pillar ;  Explain value to the audience.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Content Pillars\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Tapşırıq real hesablara giriş tələb etmir: etik kontent planı hazırlayırsan.\n**Nümunə situasiya:** Karyera məsləhəti, FAQ, təcrübə hekayəsi, proqram elanı sütunlarını qur.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Social Media Management / Task-3. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Dörd kontent sütunu müəyyən et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Hər biri üçün üç ideya yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Kontent dəyərini izah et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Karyera məsləhəti, FAQ, təcrübə hekayəsi, proqram elanı sütunlarını qur. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Content pillars matrix. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nKaryera məsləhəti, FAQ, təcrübə hekayəsi, proqram elanı sütunlarını qur.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Content pillars matrix.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Şifrə və şəxsi mesaj tələb etmə, faktı yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Content Pillars\nThis practical assignment is designed for beginners. Work on an ethical content plan without accessing real accounts.\n**Example scenario:** Define content pillars for career tips, FAQs, stories and program announcements.\n\n## Free tools and platforms\n- **Google Sheets** — https://sheets.google.com. Create a sheet, name the columns and add at least five fictional rows.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Social Media Management / Task-3. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Define four content pillars. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Draft three ideas per pillar. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Explain value to the audience. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Define content pillars for career tips, FAQs, stories and program announcements. Document what worked and any limitations.\n7. Complete the main artifact: Content pillars matrix. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nDefine content pillars for career tips, FAQs, stories and program announcements.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Content pillars matrix.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Do not request passwords or private messages; verify facts.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nContent Pillars: Dörd kontent sütunu müəyyən et. Hər biri üçün üç ideya yaz. Kontent dəyərini izah et. Pulsuz alətlər: Google Sheets. Nəticə: Content pillars matrix.\n\n[[EN]]\nContent Pillars: Define four content pillars. Draft three ideas per pillar. Explain value to the audience. Free tools: Google Sheets. Output: Content pillars matrix."},{"slug":"talora-social-media-management-2026","task_number":4,"title":"Editorial Calendar","old_instructions":"[[AZ]]\n## Məqsəd\nDörd həftəlik plan qur ;  Paylaşım vaxtı və format seç ;  İş yükünü real qiymətləndir.\n\n## Addım-addım icra\n1. Dörd həftəlik plan qur.\n2. Paylaşım vaxtı və format seç.\n3. İş yükünü real qiymətləndir.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\n28-day calendar. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nBuild a four-week calendar ;  Choose formats and posting cadence ;  Check workload realism.\n\n## Step-by-step\n1. Build a four-week calendar.\n2. Choose formats and posting cadence.\n3. Check workload realism.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nFour-week editorial calendar. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nDörd həftəlik plan qur ;  Paylaşım vaxtı və format seç ;  İş yükünü real qiymətləndir.\n\n[[EN]]\nBuild a four-week calendar ;  Choose formats and posting cadence ;  Check workload realism.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Editorial Calendar\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Tapşırıq real hesablara giriş tələb etmir: etik kontent planı hazırlayırsan.\n**Nümunə situasiya:** 28 günlük kontent planına tarix, format, kanal, məsul şəxs, CTA yaz.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Social Media Management / Task-4. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Dörd həftəlik plan qur. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Paylaşım vaxtı və format seç. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. İş yükünü real qiymətləndir. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: 28 günlük kontent planına tarix, format, kanal, məsul şəxs, CTA yaz. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: 28-day calendar. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\n28 günlük kontent planına tarix, format, kanal, məsul şəxs, CTA yaz.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** 28-day calendar.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Şifrə və şəxsi mesaj tələb etmə, faktı yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Editorial Calendar\nThis practical assignment is designed for beginners. Work on an ethical content plan without accessing real accounts.\n**Example scenario:** Build a 28-day calendar with date, format, channel, owner and CTA.\n\n## Free tools and platforms\n- **Google Sheets** — https://sheets.google.com. Create a sheet, name the columns and add at least five fictional rows.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Social Media Management / Task-4. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Build a four-week calendar. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Choose formats and posting cadence. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Check workload realism. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Build a 28-day calendar with date, format, channel, owner and CTA. Document what worked and any limitations.\n7. Complete the main artifact: Four-week editorial calendar. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nBuild a 28-day calendar with date, format, channel, owner and CTA.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Four-week editorial calendar.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Do not request passwords or private messages; verify facts.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nEditorial Calendar: Dörd həftəlik plan qur. Paylaşım vaxtı və format seç. İş yükünü real qiymətləndir. Pulsuz alətlər: Google Sheets. Nəticə: 28-day calendar.\n\n[[EN]]\nEditorial Calendar: Build a four-week calendar. Choose formats and posting cadence. Check workload realism. Free tools: Google Sheets. Output: Four-week editorial calendar."},{"slug":"talora-social-media-management-2026","task_number":5,"title":"Creative Production Brief","old_instructions":"[[AZ]]\n## Məqsəd\nİki post üçün vizual brief yaz ;  Caption və CTA əlavə et ;  Ölçü və accessibility tələblərini göstər.\n\n## Addım-addım icra\n1. İki post üçün vizual brief yaz.\n2. Caption və CTA əlavə et.\n3. Ölçü və accessibility tələblərini göstər.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nTwo post briefs. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nCreate briefs for two posts ;  Add captions and CTAs ;  Define image sizes and accessibility requirements.\n\n## Step-by-step\n1. Create briefs for two posts.\n2. Add captions and CTAs.\n3. Define image sizes and accessibility requirements.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nTwo post briefs. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nİki post üçün vizual brief yaz ;  Caption və CTA əlavə et ;  Ölçü və accessibility tələblərini göstər.\n\n[[EN]]\nCreate briefs for two posts ;  Add captions and CTAs ;  Define image sizes and accessibility requirements.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Creative Production Brief\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Tapşırıq real hesablara giriş tələb etmir: etik kontent planı hazırlayırsan.\n**Nümunə situasiya:** 1080×1350 post üçün mesaj, vizual referans, kontrast və alt text brief-i hazırla.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Canva Free** — https://www.canva.com. Yalnız Free elementlərdən istifadə et, nəticəni PNG/PDF ixrac et; Pro elementə pul vermə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Social Media Management / Task-5. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. İki post üçün vizual brief yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Caption və CTA əlavə et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Ölçü və accessibility tələblərini göstər. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: 1080×1350 post üçün mesaj, vizual referans, kontrast və alt text brief-i hazırla. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Two post briefs. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\n1080×1350 post üçün mesaj, vizual referans, kontrast və alt text brief-i hazırla.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Two post briefs.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Şifrə və şəxsi mesaj tələb etmə, faktı yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Creative Production Brief\nThis practical assignment is designed for beginners. Work on an ethical content plan without accessing real accounts.\n**Example scenario:** Create a 1080×1350 post brief with message, contrast and alt text.\n\n## Free tools and platforms\n- **Canva Free** — https://www.canva.com. Use only Free elements, export PNG/PDF and avoid Pro assets.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Social Media Management / Task-5. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Create briefs for two posts. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Add captions and CTAs. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Define image sizes and accessibility requirements. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Create a 1080×1350 post brief with message, contrast and alt text. Document what worked and any limitations.\n7. Complete the main artifact: Two post briefs. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nCreate a 1080×1350 post brief with message, contrast and alt text.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Two post briefs.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Do not request passwords or private messages; verify facts.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nCreative Production Brief: İki post üçün vizual brief yaz. Caption və CTA əlavə et. Ölçü və accessibility tələblərini göstər. Pulsuz alətlər: Canva Free. Nəticə: Two post briefs.\n\n[[EN]]\nCreative Production Brief: Create briefs for two posts. Add captions and CTAs. Define image sizes and accessibility requirements. Free tools: Canva Free. Output: Two post briefs."},{"slug":"talora-social-media-management-2026","task_number":6,"title":"Community Response Playbook","old_instructions":"[[AZ]]\n## Məqsəd\nSual, tənqid və spam ssenarisi yarat ;  Cavab tonunu müəyyən et ;  Eskalasiya və məxfilik qaydalarını yaz.\n\n## Addım-addım icra\n1. Sual, tənqid və spam ssenarisi yarat.\n2. Cavab tonunu müəyyən et.\n3. Eskalasiya və məxfilik qaydalarını yaz.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nModeration playbook. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nDraft FAQ, complaint and spam scenarios ;  Set response tone ;  Document escalation and privacy.\n\n## Step-by-step\n1. Draft FAQ, complaint and spam scenarios.\n2. Set response tone.\n3. Document escalation and privacy.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nModeration playbook. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nSual, tənqid və spam ssenarisi yarat ;  Cavab tonunu müəyyən et ;  Eskalasiya və məxfilik qaydalarını yaz.\n\n[[EN]]\nDraft FAQ, complaint and spam scenarios ;  Set response tone ;  Document escalation and privacy.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Community Response Playbook\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Tapşırıq real hesablara giriş tələb etmir: etik kontent planı hazırlayırsan.\n**Nümunə situasiya:** Gecikmiş müraciət sualı, spam və təhqir üçün nəzakətli cavab/escalation yaz.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Social Media Management / Task-6. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Sual, tənqid və spam ssenarisi yarat. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Cavab tonunu müəyyən et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Eskalasiya və məxfilik qaydalarını yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Gecikmiş müraciət sualı, spam və təhqir üçün nəzakətli cavab/escalation yaz. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Moderation playbook. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nGecikmiş müraciət sualı, spam və təhqir üçün nəzakətli cavab/escalation yaz.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Moderation playbook.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Şifrə və şəxsi mesaj tələb etmə, faktı yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Community Response Playbook\nThis practical assignment is designed for beginners. Work on an ethical content plan without accessing real accounts.\n**Example scenario:** Draft polite responses and escalation rules for application delays and spam.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Social Media Management / Task-6. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Draft FAQ, complaint and spam scenarios. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Set response tone. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Document escalation and privacy. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Draft polite responses and escalation rules for application delays and spam. Document what worked and any limitations.\n7. Complete the main artifact: Moderation playbook. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nDraft polite responses and escalation rules for application delays and spam.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Moderation playbook.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Do not request passwords or private messages; verify facts.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nCommunity Response Playbook: Sual, tənqid və spam ssenarisi yarat. Cavab tonunu müəyyən et. Eskalasiya və məxfilik qaydalarını yaz. Pulsuz alətlər: Google Docs. Nəticə: Moderation playbook.\n\n[[EN]]\nCommunity Response Playbook: Draft FAQ, complaint and spam scenarios. Set response tone. Document escalation and privacy. Free tools: Google Docs. Output: Moderation playbook."},{"slug":"talora-social-media-management-2026","task_number":7,"title":"Content Experiment","old_instructions":"[[AZ]]\n## Məqsəd\nBir hook və ya format hipotezi qur ;  Sintetik A/B nəticələri müqayisə et ;  Hansı nəticənin mənalı olduğunu izah et.\n\n## Addım-addım icra\n1. Bir hook və ya format hipotezi qur.\n2. Sintetik A/B nəticələri müqayisə et.\n3. Hansı nəticənin mənalı olduğunu izah et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nSocial experiment worksheet. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nForm a hook/format hypothesis ;  Compare synthetic A/B results ;  Explain uncertainty.\n\n## Step-by-step\n1. Form a hook/format hypothesis.\n2. Compare synthetic A/B results.\n3. Explain uncertainty.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nExperiment worksheet. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nBir hook və ya format hipotezi qur ;  Sintetik A/B nəticələri müqayisə et ;  Hansı nəticənin mənalı olduğunu izah et.\n\n[[EN]]\nForm a hook/format hypothesis ;  Compare synthetic A/B results ;  Explain uncertainty.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Content Experiment\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Tapşırıq real hesablara giriş tələb etmir: etik kontent planı hazırlayırsan.\n**Nümunə situasiya:** Sual ilə başlayan hook və fayda ilə başlayan hook-u demo A/B məlumatında müqayisə et.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Social Media Management / Task-7. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Bir hook və ya format hipotezi qur. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Sintetik A/B nəticələri müqayisə et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Hansı nəticənin mənalı olduğunu izah et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Sual ilə başlayan hook və fayda ilə başlayan hook-u demo A/B məlumatında müqayisə et. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Social experiment worksheet. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nSual ilə başlayan hook və fayda ilə başlayan hook-u demo A/B məlumatında müqayisə et.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Social experiment worksheet.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Şifrə və şəxsi mesaj tələb etmə, faktı yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Content Experiment\nThis practical assignment is designed for beginners. Work on an ethical content plan without accessing real accounts.\n**Example scenario:** Compare question-led and benefit-led hooks with fictional A/B data.\n\n## Free tools and platforms\n- **Google Sheets** — https://sheets.google.com. Create a sheet, name the columns and add at least five fictional rows.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Social Media Management / Task-7. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Form a hook/format hypothesis. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Compare synthetic A/B results. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Explain uncertainty. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Compare question-led and benefit-led hooks with fictional A/B data. Document what worked and any limitations.\n7. Complete the main artifact: Experiment worksheet. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nCompare question-led and benefit-led hooks with fictional A/B data.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Experiment worksheet.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Do not request passwords or private messages; verify facts.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nContent Experiment: Bir hook və ya format hipotezi qur. Sintetik A/B nəticələri müqayisə et. Hansı nəticənin mənalı olduğunu izah et. Pulsuz alətlər: Google Sheets. Nəticə: Social experiment worksheet.\n\n[[EN]]\nContent Experiment: Form a hook/format hypothesis. Compare synthetic A/B results. Explain uncertainty. Free tools: Google Sheets. Output: Experiment worksheet."},{"slug":"talora-social-media-management-2026","task_number":8,"title":"Analytics Reporting","old_instructions":"[[AZ]]\n## Məqsəd\nReach, engagement və click metric-lərini seç ;  Həftəlik dashboard hazırla ;  Vanity metric-ləri ayır.\n\n## Addım-addım icra\n1. Reach, engagement və click metric-lərini seç.\n2. Həftəlik dashboard hazırla.\n3. Vanity metric-ləri ayır.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nInsights dashboard. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nSelect reach, engagement and click KPIs ;  Build a weekly dashboard ;  Flag vanity metrics.\n\n## Step-by-step\n1. Select reach, engagement and click KPIs.\n2. Build a weekly dashboard.\n3. Flag vanity metrics.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nInsights dashboard. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nReach, engagement və click metric-lərini seç ;  Həftəlik dashboard hazırla ;  Vanity metric-ləri ayır.\n\n[[EN]]\nSelect reach, engagement and click KPIs ;  Build a weekly dashboard ;  Flag vanity metrics.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Analytics Reporting\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Tapşırıq real hesablara giriş tələb etmir: etik kontent planı hazırlayırsan.\n**Nümunə situasiya:** Reach, comments, saves və clicks üçün həftəlik hesabat hesabla.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Social Media Management / Task-8. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu 